L2_1.m_Talk_KOREA = "<b>어둠의 해커 9인방. 통칭 다─크 세븐.</b>"
L2_1.m_fTalkTime = 0.03
L2_1.m_Talk_JPN = "<b>闇のハッカー9人組。通称ダークセブン。</b>"
L2_1.m_Talk_ENG = "<b>The Nine Great Hackers of Darkness. A.K.A. Daark Seven.</b>"
