L2_1.m_Talk_THA = "<b>เก้ายอดแฮ็กเกอร์แห่งความมืด หรือที่รู้จักในนามดาร์กเซเว่น</b>"
L2_1.m_Talk_VTN = "<b>Chín Hacker Vĩ Đại của Bóng Tối A.K.A. Dark Seven.</b>"
L2_1.m_Talk_SCN = "<b>藏身于黑暗的黑客九人帮。统称Dark 7。</b>"
L2_1.m_Talk_DEU = "<b>Die Neun Großen Hacker der Finsternis, auch bekannt als Dark Seven.</b>"
L2_1.m_Talk_FRA = "<b>Les neuf super hackeurs des ténèbres, alias Dark Seven.</b>"
L3_1 = {}
L3_1.m_CutScenKey_Talk = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 31225
L3_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Talk_KOREA = "<b>그들은 사회의 이면에서 암약하며 기업의 횡포와 범죄 조직의 악행을 폭로한다.</b>"
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "<b>彼らは社会の裏側で暗躍し、企業の横暴と犯罪組織の悪行を暴露する。</b>"
L3_1.m_Talk_ENG = "<b>They remain hidden among us as they expose the machinations of multinational conglomerates and criminal organizations.</b>"
L3_1.m_Talk_TWN = "<b>他們在社會裡暗中活躍，揭露企業的橫行與犯罪組織的惡行。</b>"
L3_1.m_Talk_THA = "<b>พวกเขาแฝงกายอยู่ท่ามกลางเรา และแฉกลไกของกลุ่มธุรกิจข้ามชาติและองค์กรอาชญากรรม</b>"
L3_1.m_Talk_VTN = "<b>Họ vẫn ẩn nấp giữa chúng ta khi họ vạch trần âm mưu của các tập đoàn đa quốc gia và các tổ chức tội phạm.</b>"
L3_1.m_Talk_SCN = "<b>他们在社会阴暗面中秘密活动着，揭露企业的横行霸道与犯罪组织的恶行。</b>"
L3_1.m_Talk_DEU = "<b>Aus dem Verborgenen decken sie Machenschaften multinationaler Konzerne und krimineller Organisationen auf.</b>"
L3_1.m_Talk_FRA = "<b>Ces anonymes révèlent au grand jour les manigances des multinationales et des organisations criminelles.</b>"
L4_1 = {}
