L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 31225
L4_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Talk_KOREA = "<b>알파트릭스의 무차별적인 경제 침공이 갑작스럽게 중단된 것도,</b>"
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "<b>アルファトリックスの無差別的な経済侵攻が突然中断したのも、</b>"
L4_1.m_Talk_ENG = "<b>The wanton economic invasion of Alphatrix came to a halt,</b>"
L4_1.m_Talk_TWN = "<b>阿爾法崔克斯無差別的經濟侵略突然中斷也是,</b>"
L4_1.m_Talk_THA = "<b>การรุกรานทางเศรษฐกิจอันละโมภของอัลฟาทริกซ์ต้องหยุดลง</b>"
L4_1.m_Talk_VTN = "<b>Cuộc xâm lược kinh tế bừa bãi của Alphatrix đã phải ngừng lại,</b>"
L4_1.m_Talk_SCN = "<b>阿尔法崔克斯的经济侵略突然中断也是,</b>"
L4_1.m_Talk_DEU = "<b>Die mutwillige wirtschaftliche Invasion von Alphatrix kam zum Erliegen.</b>"
L4_1.m_Talk_FRA = "<b>L'invasion économique injustifiée d'Alphatrix a cessé,</b>"
L5_1 = {}
