L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Talk_KOREA = "<b>사악한 악의 조직 리플레이서 신디케이트를 파멸로 몰아 넣은 것도,</b>"
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "<b>腹黒い悪の組織リプレイサー・シンジケートを破滅に追いやったのも、</b>"
L5_1.m_Talk_ENG = "<b>and the evil Replacer Syndicate met its doom,</b>"
L5_1.m_Talk_TWN = "<b>邪惡組織克隆集團被逼入絕境也是,</b>"
L5_1.m_Talk_THA = "<b>และรีเพลสเซอร์ซินดิเคตที่ชั่วร้ายถึงจุดจบ</b>"
L5_1.m_Talk_VTN = "<b>và Nghiệp Đoàn Nhân Bản độc ​​ác đã gặp phải sự diệt vong,</b>"
L5_1.m_Talk_SCN = "<b>将邪恶组织克隆集团逼入绝境的也是,</b>"
L5_1.m_Talk_DEU = "<b>Und das böse Replacer-Syndikat fand seinen Untergang.</b>"
L5_1.m_Talk_FRA = "<b>et le Syndicat des substituts a été mis hors d'état de nuire,</b>"
L6_1 = {}
