L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Talk_KOREA = "<b>그 이면에는 모두 다─크 세븐의 활약이 있었다.</b>"
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "<b>その裏側にはいつもダークセブンの活躍があった。</b>"
L6_1.m_Talk_ENG = "<b>all thanks to the behind-the-scene efforts of Daark Seven.</b>"
L6_1.m_Talk_TWN = "<b>甚至在異界都有Dark 7活躍的身影。</b>"
L6_1.m_Talk_THA = "<b>ทั้งหมดเกิดขึ้นได้เพราะความพยายามเบื้องหลังของดาร์กเซเว่น</b>"
L6_1.m_Talk_VTN = "<b>tất cả là nhờ những nỗ lực phía sau của Dark Seven.</b>"
L6_1.m_Talk_SCN = "<b>甚至在异界也有Dark 7活跃的身影。</b>"
L6_1.m_Talk_DEU = "<b>Das alles nur dank der geheimen Bemühungen von Dark Seven!</b>"
L6_1.m_Talk_FRA = "<b>grâce aux efforts du mystérieux groupe Dark Seven.</b>"
L7_1 = {}
L7_1.m_CutScenKey_Talk = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 31225
L7_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Talk_KOREA = "<b>그렇다! 다─크 세븐은 바로 왜곡된 체제에 저항하는 고독한 다─크 히어로인 것이다!</b>"
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "<b>そう！　ダークセブンは歪曲された体制に抵抗する孤独なダークヒーローなのである！</b>"
L7_1.m_Talk_ENG = "<b>That's right! Daark Seven is our unsung Dark Hero resisting against the nefarious system!</b>"
L7_1.m_Talk_TWN = "<b>沒錯！Dark 7正是抵抗這世間扭曲體制的黑暗英雄！</b>"
L7_1.m_Talk_THA = "<b>ใช่แล้ว ดาร์กเซเว่นคือฮีโร่แห่งด้านมืดที่ไม่มีใครรู้จัก ซึ่งลุกขึ้นต่อต้านระบบอันเลวร้าย</b>"
L7_1.m_Talk_VTN = "<b>Đúng vậy! Dark Seven là vị Anh Hùng Bóng Tối vô danh của chúng ta, chống lại những hệ thống bất chính!</b>"
L7_1.m_Talk_SCN = "<b>没错！Dark 7正是抵抗这世间扭曲体制的黑暗英雄！</b>"
L7_1.m_Talk_DEU = "<b>So ist es! Dark Seven ist ein unbesungener finsterer Held, der sich gegen das schändliche System wehrt!</b>"
L7_1.m_Talk_FRA = "<b>Exactement ! Dark Seven, les héros qui luttent dans l'ombre contre les excès du système !</b>"
