L10_1.m_bCharHologramEffect = true
L10_1.m_Talk_KOREA = "들을 때마다 쪽팔려 죽겠네, 진짜."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "本当、何回聞いても恥ずかしいわ。"
L10_1.m_Talk_ENG = "I'm so embarrassed every time I hear it."
L10_1.m_Talk_TWN = "每次聽都覺得羞恥死了，真是的。"
L10_1.m_Talk_THA = "ได้ยินทีไรก็อายทุกที"
L10_1.m_Talk_VTN = "Tôi rất xấu hổ mỗi khi nghe thứ này."
L10_1.m_Talk_SCN = "每次听都感觉羞耻死了，真是的。"
L10_1.m_Talk_DEU = "Es ist mir jedes Mal peinlich, wenn ich das höre."
L10_1.m_Talk_FRA = "Ça me met mal à l'aise chaque fois que j'entends ça."
