L12_1 = {}
L12_1.m_CutScenKey_Talk = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 31225
L12_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_StartBGMFileName = "CUTSCENE_TALK_01"
L12_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L12_1.m_Talk_KOREA = "무슨 소리야? 저것만큼 우리에 대해 잘 설명해 주는 코멘트가 또 어디 있어?"
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "そう？　私たちについてあんなきちんと説明されたコメント、他で見たことないけど。"
L12_1.m_Talk_ENG = "What do you mean? No comment explains who we are better than that!"
L12_1.m_Talk_TWN = "你在說什麼？這不是對我們最好的說明和評價嗎？"
L12_1.m_Talk_THA = "หมายความว่าไง? ไม่มีความเห็นไหนอธิบายเราได้ดีกว่านี้เลยนะ!"
L12_1.m_Talk_VTN = "Ý cậu là sao? Không có bình luận nào giải thích chúng ta tốt hơn thứ đó!"
L12_1.m_Talk_SCN = "你说什么呢？这不是对我们最好的说明和评价吗？"
L12_1.m_Talk_DEU = "Was meinen Sie? Nichts erklärt besser, wer wir sind!"
L12_1.m_Talk_FRA = "Pourquoi ? Personne ne peut expliquer mieux que nous ce qu'on fait !"
L13_1 = {}
L13_1.m_CutScenKey_Talk = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 31225
L13_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_HATE"
L13_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L13_1.m_Pos = "C"
L13_1.m_Talk_KOREA = "뭘 설명해 줘? 알파트릭스 불매 운동 게시글에 좋아요 하나 찍어 준 거?"
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "何が説明よ。アルファトリックス不買運動コメントに、いいね一つしかなかったくせに。"
L13_1.m_Talk_ENG = "Explains what, exactly? How we gave one \"like\" to the social media post boycotting Alphatrix products?"
L13_1.m_Talk_TWN = "說明什麼了？抵制阿爾法崔克斯運動的聊天串有幾個讚？"
L13_1.m_Talk_THA = "อธิบายอะไรกันแน่? วิธีที่เรากด \"ถูกใจ\" โพสต์สื่อโซเชียลที่แบนผลิตภัณฑ์อัลฟาทริกซ์น่ะเหรอ?"
L13_1.m_Talk_VTN = "Giải thích chính xác thứ gì mới được chứ? Chúng ta tặng một \"like\" cho bài đăng tẩy chay các sản phẩm của Alphatrix trên mạng xã hội thì sao?"
L13_1.m_Talk_SCN = "说明什么了？在抵制阿尔法崔克斯运动的帖子下点了个赞？"
L13_1.m_Talk_DEU = "Was genau erklärt es? Dass wir den Social-Media-Aufruf zum Boykott von Alphatrix-Produkten mit einem „Like“ gewürdigt haben?"
L13_1.m_Talk_FRA = "Expliquer quoi, exactement ? Comment on a mis un like à un post appelant au boycott des produits Alphatrix ?"
