L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 31225
L15_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L15_1.m_bWaitClick = true
