L15_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L15_1.m_Talk_KOREA = "두 개였어! 나랑 앨버트 것까지!"
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "二つ！　アルバートの分も含めて！"
L15_1.m_Talk_ENG = "Two likes! Mine and Albert's!"
L15_1.m_Talk_TWN = "兩個讚！我，還有亞伯特的！"
L15_1.m_Talk_THA = "ถูกใจสองครั้งสิ! ของฉันกับอัลเบิร์ต!"
L15_1.m_Talk_VTN = "Hai like nhé! Của tôi và của Albert!"
L15_1.m_Talk_SCN = "是两个赞！我的，还有艾伯特的！"
L15_1.m_Talk_DEU = "Zwei Likes: meiner und Alberts!"
L15_1.m_Talk_FRA = "Deux likes ! Le mien et celui d'Albert !"
L16_1 = {}
L16_1.m_CutScenKey_Talk = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 31225
L16_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L16_1.m_Talk_KOREA = "괜찮아, 매버릭. 넘버 2는 우리 조직에 들어온 지 얼마 안 되어서 그래."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "大丈夫、マーベリック。ナンバー2はこの組織に入ったばかりだから。"
L16_1.m_Talk_ENG = "It's okay, Maverick. Number 2 hasn't acclimated to our group yet, that's all."
L16_1.m_Talk_TWN = "沒關係，麥伯利。NO.2是因為剛進組織不久，還沒適應過來。"
L16_1.m_Talk_THA = "ไม่เป็นไรนะ มาเวอริก หมายเลข 2 ยังไม่คุ้นเคยกลับกลุ่มของเราดีก็แค่นั้นเอง"
L16_1.m_Talk_VTN = "Được rồi, Maverick. Số 2 vẫn chưa quen thuộc trong nhóm của chúng ta cho lắm, chỉ thế thôi."
L16_1.m_Talk_SCN = "没关系，麦博利，2号是因为刚进组织不久，还没适应过来。"
L16_1.m_Talk_DEU = "Ist schon gut, Maverick. Nummer 2 hat sich noch nicht in unsere Gruppe eingelebt, das ist alles."
L16_1.m_Talk_FRA = "Ça va, Maverick. C'est juste que numéro 2 n'est pas encore habituée à notre fonctionnement."
L17_1 = {}
L17_1.m_CutScenKey_Talk = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 31225
L17_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_DESPAIR"
L17_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L17_1.m_Pos = "C"
L17_1.m_Talk_KOREA = "그리고 9인방이라니, 나 오기 전에도 너네 다 합쳐서 세 명밖에 없었잖아."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "それに9人組って、アタシが来る前だってアンタたち合わせて3人しかいなかったじゃない。"
L17_1.m_Talk_ENG = "And \"Nine\" Great Hackers? There was only three of you before I came... and it doesn't even match our name."
L17_1.m_Talk_TWN = "還有，9人幫是什麼啦，在我來之前也只有3個人啊。"
L17_1.m_Talk_THA = "ส่วนยอดแฮ็กเกอร์ทั้ง \"เก้า\"? ก่อนที่ฉันจะมาถึง มีพวกนายแค่สามคน... แต่มันก็ไม่ตรงกับชื่อเราด้วยซ้ำ"
L17_1.m_Talk_VTN = "Và \"Chín\" Hacker Vĩ Đại? Các bạn chỉ có ba người trước khi tôi gia nhập... và con số hiện tại thậm chí còn không khớp với tên của chúng ta."
L17_1.m_Talk_SCN = "还有，什么九人帮啊，明明我来之前也就只有3个人好嘛。"
L17_1.m_Talk_DEU = "Wieso sind es eigentlich „neun“ Große Hacker? Bevor ich dazukam, wart ihr nur zu dritt … und unserem Namen entspricht es auch nicht."
L17_1.m_Talk_FRA = "Et pourquoi les « neuf » super hackeurs ? Vous étiez trois avant que je vous rejoigne... et ça ne colle même pas avec notre nom."
