L19_1 = {}
L19_1.m_CutScenKey_Talk = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 31225
L19_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L19_1.m_Talk_KOREA = "크흠. 그건 일종의 TO 같은 거야. 빈 자리가 있어야 실력자들을 뽑을 수 있으니까."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "ゴホン。それはある種のTOみたいなもので、常に空席がなきゃ実力者たちを引き抜けない。"
L19_1.m_Talk_ENG = "Ahem. It's a sort of a designated vacancy. We need to leave some slots open to accept new talent."
L19_1.m_Talk_TWN = "喔，那是某種成員編制表之類的啦，因為要為將來選拔出的人才留空位啊。"
L19_1.m_Talk_THA = "อะแฮ่ม มันคือที่ว่างที่กำหนดไว้แล้วน่ะ เราต้องเหลือที่ไว้รับคนเก่งๆ คนใหม่ด้วย"
L19_1.m_Talk_VTN = "E hèm. Đó là một loại vị trí tuyển dụng được chỉ định. Chúng ta cần để ngỏ một số vị trí để tiếp nhận tài năng mới."
L19_1.m_Talk_SCN = "咳咳，那是某种成员编制表之类的啦，因为要为将来选拔出的人才留空位啊。"
L19_1.m_Talk_DEU = "Es handelt sich um eine Art ausgewiesene freie Stelle. Wir lassen einige Plätze frei, um neue Talente aufzunehmen."
L19_1.m_Talk_FRA = "Hum. C'est des sortes de postes à pourvoir. Ce serait bête de fermer la porte à des candidats potentiels."
L20_1 = {}
L20_1.m_CutScenKey_Talk = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 31225
L20_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_IDLE"
L20_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L20_1.m_Pos = "C"
L20_1.m_Talk_KOREA = "그냥 멋있어 보여서 9인방으로 한 게 아니라?"
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "カッコいい響きだったから9人組にしたんじゃなくて？"
L20_1.m_Talk_ENG = "You didn't just randomly pick 9 because it sounded cool?"
L20_1.m_Talk_TWN = "你只是因為聽起來很帥所以叫9人幫吧？"
L20_1.m_Talk_THA = "นายไม่ได้เลือกเลข 9 ขึ้นมาแค่เพราะว่ามันเท่เหรอ?"
L20_1.m_Talk_VTN = "Không phải bạn chọn ngẫu nhiên số 9 vì nó nghe ngầu ra phết sao?"
L20_1.m_Talk_SCN = "只是因为听起来很帅叫九人帮的吧？"
L20_1.m_Talk_DEU = "Seid ihr sicher, dass ihr „neun“ nicht nur genommen habt, weil es sich cool anhört?"
L20_1.m_Talk_FRA = "Et pourquoi « 9 », ça sonnait bien, c'est ça ?"
