L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 31225
L23_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L23_1.m_Talk_KOREA = "빨리 무슨 핑계라도 대 봐. 이러다 들키겠어."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "早く何か言い訳でもいいからして。このままじゃバレちゃう。"
L23_1.m_Talk_ENG = "Come on, say something. She's going to catch on."
L23_1.m_Talk_TWN = "趕快隨便想個藉口，這樣下去會被發現的。"
L23_1.m_Talk_THA = "ไม่เอาน่า พูดอะไรหน่อยสิ เดี๋ยวเธอก็เข้าใจ"
L23_1.m_Talk_VTN = "Thôi nào, hãy nói chuyện gì đó đi. Cô ấy sẽ bắt kịp thôi."
L23_1.m_Talk_SCN = "赶紧随便想个借口啊，这样下去会被发现的。"
L23_1.m_Talk_DEU = "Komm schon, sag was, sonst kriegt sie was mit."
L23_1.m_Talk_FRA = "Vas-y, dis quelque chose. Elle va comprendre."
L24_1 = {}
