L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 31225
L24_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L24_1.m_bWaitClick = true
