L24_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L24_1.m_Talk_KOREA = "그런 말은 개인 채널로 해, 얼간아!"
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "そういう話は個人チャットですべきでしょ、バカ！"
L24_1.m_Talk_ENG = "You should send that as a DM, you moron!"
L24_1.m_Talk_TWN = "這種話在個人頻道裡說啦，笨蛋！"
L24_1.m_Talk_THA = "น่าจะส่งมาเป็นข้อความหลังไมค์นะ ไอ้โง่เอ๊ย!"
L24_1.m_Talk_VTN = "Cậu nên gửi trong tin nhắn riêng tư ấy, đồ ngu!"
L24_1.m_Talk_SCN = "这种话在个人频道里说啊，笨蛋！"
L24_1.m_Talk_DEU = "Du solltest es als DM schicken, du Idiot!"
L24_1.m_Talk_FRA = "C'est pas pour les chiens les MP, pauvre débile !"
