L28_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L29_1 = "리더! 기다렸어!"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "リーダー！　待ってました！"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Leader! We've been waiting for you!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "老大！等你好久了！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "หัวหน้า! เรารอคุณอยู่นะ!"
L28_1.m_Talk_THA = L29_1
L29_1 = "Lãnh Đạo! Chúng tôi chờ anh nãy giờ!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "老大！等你好久了！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Anführer, wir haben auf dich gewartet!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Chef ! On vous attendait !"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@29#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 29
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 31225
L29_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L30_1 = "오늘도 멋진 무용담을 들을 수 있겠죠? 기대 중입니다!"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "今日も素敵な武勇伝を聞けるんですよね？　すごく楽しみです！"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Can we hear your amazing stories again? We're looking forward to it!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "今天也可以聽到你帥氣的英雄故事吧？我很期待喔！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "เล่าเรื่องเจ๋งๆ ของคุณให้เราฟังอีกได้มั้ย? เรารอฟังอยู่เนี่ย!"
L29_1.m_Talk_THA = L30_1
L30_1 = "Chúng tôi có thể nghe lại những câu chuyện tuyệt vời của anh không? Chúng tôi thích chúng lắm!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "今天也可以听到帅气的英雄故事吧？我很期待！"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Wir freuen uns schon darauf, wieder deine tollen Geschichten zu hören!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Vous voulez bien nous raconter encore vos histoires ? On les adore !"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@30#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 30
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 31225
L30_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "MACHINEGAP_COFFIN_DARK_NULL"
L31_1 = "여기는 내 개인적인 활약이나 뽐내자고 모이는 자리가 아냐. 그렇지 않나, 제군들."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ここは私の個人的な活躍を自慢するために集まった場所ではない。そうだろう？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "This isn't the place for me to show off my achievements. Isn’t that right, troops?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "我們聚在這裡並不是為了公開我個人的活躍表現。不是嗎，諸君？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "นี่ไม่ใช่ที่ที่ฉันจะอวดอ้างความสำเร็จของตัวเองนะ ถูกมั้ย นักสู้?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Đây không phải là nơi tôi khoang khoe thành tích của mình. Không đúng vậy sao, các binh sĩ?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "我们聚在这里并不是因为我个人的活跃与炫耀。不是吗，诸君？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Dies ist nicht der rechte Ort, um mit meinen Erfolgen zu prahlen, nicht wahr, Truppen?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Je ne suis pas là pour me vanter de mes exploits. Pas vrai, fidèles soldats ?"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@31#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 31
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 31225
L31_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "MACHINEGAP_COFFIN_DARK_NULL"
L32_1 = "우리는 어둠 속에서 세계를 수호하는 하나이자 아홉! 아홉이자 하나인 동지들이지!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "私たちは闇の中で世界を守る一つであり九つ！　九つであり一つの同志だ！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "We protect the world from the darkness. Nine for one! One for nine!"
L31_1.m_Talk_ENG = L32_1
L32_1 = "我們是在黑暗中守護世界的9人幫！是為同樣的理想聚集在這裡的同志！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "เราป้องโลกจากความมืด เก้าเพื่อหนึ่ง! หนึ่งเพื่อเก้า!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Chúng ta bảo vệ thế giới khỏi bóng tối. Chín người vì một người! Một người vì chín người!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "我们是在黑暗中守护世界的九人帮！大家志同道合！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Wir schützen die Welt vor der Finsternis. Neun für einen, einer für neun!"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Nous devons protéger le monde des ténèbres. Neuf pour un, un pour neuf !"
L31_1.m_Talk_FRA = L32_1
