L46_1.m_Talk_VTN = L47_1
L47_1 = "这……名字有点微妙啊。令人有点不爽。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Der Name kommt mir irgendwie bekannt vor … Ich fühle mich fast beleidigt."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Ils n'ont rien trouvé de plus... original ? C'est presque insultant."
