L7_1 = "FX_CUTSCEN_TADA"
L6_1.m_StartFXSoundName = L7_1
L6_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L7_1 = "그럼! 무단 쓰레기 투기자들을 잡아냈지!"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "もちろん！　ごみの不法投棄者を捕まえた！"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Absolutely! I caught some fly-tippers!"
L6_1.m_Talk_ENG = L7_1
L7_1 = "當然了！我抓到他們隨便亂丟垃圾！"
L6_1.m_Talk_TWN = L7_1
L7_1 = "แน่นอนครับ! ผมเจอคนทิ้งขยะผิดกฎหมาย!"
L6_1.m_Talk_THA = L7_1
L7_1 = "Chắc chắn rồi! Tôi đã bắt được mấy người xả rác bừa bãi!"
L6_1.m_Talk_VTN = L7_1
L7_1 = "当然！我找到了一群人渣资本家！"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Auf jeden Fall! Ich habe ein paar illegale Müllentsorger erwischt!"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Carrément ! Plusieurs dépôts d'ordures sauvages !"
L6_1.m_Talk_FRA = L7_1
