L8_1 = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 31225
L7_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L8_1 = "얼굴을 찍어다 대문짝만 하게 인쇄해서 투기 장소에 붙여 뒀으니까, 당분간 부끄러워서 얼굴도 못 들고 다닐걸?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "キャプチャーした顔を拡大して投棄場所に貼り付けておいたから、しばらくは恥ずかしくて外を歩けないと思う。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "I printed their faces and posted them all over town. I bet they'll be so ashamed that they'll have to keep their faces hidden!"
L7_1.m_Talk_ENG = L8_1
L8_1 = "我把他們的臉拍下來，印成跟門一樣大的大小，然後貼到他們亂丟垃圾的地方，這段時間他們應該會丟臉得抬不起頭吧？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ผมพิมพ์ใบหน้าของพวกเขาออกมาแปะไว้ทั่วเมืองแล้ว พนันได้เลยว่าพวกนั้นจะต้องอายจนต้องปิดหน้าปิดตาเลยทีเดียว!"
L7_1.m_Talk_THA = L8_1
L8_1 = "Tôi đã in khuôn mặt của họ và dán chúng khắp thị trấn. Tôi cá rằng họ sẽ xấu hổ đến mức không biết phải giấu mặt vào đâu!"
L7_1.m_Talk_VTN = L8_1
L8_1 = "我把他们的照片印成门这么大，贴到了投资大厦上，这段时间他们应该会因为丢脸而抬不起头吧？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ich habe ihre Gesichter ausgedruckt und in der ganzen Stadt aufgehängt. Sie werden sich so sehr schämen, dass sie nie wieder ihr Gesicht zeigen können!"
L7_1.m_Talk_DEU = L8_1
L8_1 = "J'ai imprimé les photos des mecs et je les ai placardées partout. Ils vont avoir tellement honte qu'ils oseront plus sortir à visage découvert !"
L7_1.m_Talk_FRA = L8_1
