L10_1 = "기껏 침투해서 한 게 그거야? 좀 더 생산적인 일도 가능하잖아?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "侵入までして、たったそれだけ？　もう少し生産的なことも可能じゃない？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "That's all you got from that? Couldn't you have done something a little more productive?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "大費周章地駭進去，結果就這樣？難道不能做點有建設性的事情嗎？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ได้มาแค่นั้นเองเหรอ? นายทำอะไรที่สร้างสรรค์กว่านี้ไม่ได้เลยเหรอ?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Đó là tất cả những gì bạn làm được à? Bạn không thể làm việc khác hiệu quả hơn sao?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "大费周章黑进去，结果就这？难道不能做点有建设性的事情吗？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Mehr hast du nicht zu bieten? Hättest du nicht etwas produktiver sein können?"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Et c'est tout ? Tu pouvais pas faire quelque chose d'un peu plus productif ?"
L9_1.m_Talk_FRA = L10_1
