L12_1.m_fTalkTime = 0.03
L13_1 = "道を綺麗にすることより、生産的なことなんてあるわけない。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "There's nothing more productive than keeping our streets clean."
L12_1.m_Talk_ENG = L13_1
L13_1 = "有什麼事情比保持街道乾淨更有建設性了。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ไม่มีอะไรสร้างสรรค์ไปกว่าการทำให้ท้องถนนของเราสะอาดแล้ว"
L12_1.m_Talk_THA = L13_1
L13_1 = "Không có gì hiệu quả hơn chuyện giữ cho đường phố của chúng ta sạch sẽ đâu."
L12_1.m_Talk_VTN = L13_1
L13_1 = "哪儿有比清理街道垃圾更有建设性的事情。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Nichts ist produktiver, als unsere Straßen sauber zu halten."
L12_1.m_Talk_DEU = L13_1
