L16_1 = "넘버 2가 이해해 줘. 매버릭 녀석은 예전부터 정말 중요한 일이 뭔지 구분을 못했거든."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "マーベリックは昔から本当に重要なことが何なのか、ちゃんと区別できないの。\nだから、ナンバー2も理解してあげて。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Cut him a little slack, number 2. Maverick was never good at realizing what's most important."
L15_1.m_Talk_ENG = L16_1
L16_1 = "NO.2，你就理解一下吧。麥伯利這傢伙從來分不清什麼是真正重要的事情。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "หยวนๆ เถอะ หมายเลข 2 มาเวอริกไม่เคยถนัดเรื่องแยกแยะความสำคัญอยู่แล้ว"
L15_1.m_Talk_THA = L16_1
L16_1 = "Cho cậu ta ít thời gian đi, số 2. Maverick không giỏi trong việc nhận ra chuyện gì mới là quan trọng nhất đâu."
L15_1.m_Talk_VTN = L16_1
L16_1 = "2号，你就理解一下吧，麦博利这家伙从来分不清什么是真正重要的事情。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Sei nachsichtig mit ihm, Nummer 2. Maverick war nie gut darin, das Wichtigste zu erkennen."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Ne sois pas trop dur avec lui, numéro 2. Maverick n'a jamais su ce qui était vraiment important."
L15_1.m_Talk_FRA = L16_1
