L19_1 = "Lẽ ra cậu ta cũng nên trừng phạt những kẻ không tái chế nữa!"
L18_1.m_Talk_VTN = L19_1
L19_1 = "既然要清理街道垃圾，就该把那帮不做垃圾分类的家伙也一起收拾了！"
