L21_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L22_1 = "아차! 역시 앨버트 말이 맞아. 다음에는 잊지 않겠어!"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
