L21_1.m_Talk_THA = L22_1
L22_1 = "Úi! Cậu nói đúng đấy, Albert. Lần sau tôi sẽ không quên vụ này đâu!"
L21_1.m_Talk_VTN = L22_1
L22_1 = "哎呀！果然还是艾伯特说的没错。下次我不会再忘了！"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Oh! Du hast recht, Albert. Das nächste Mal werde ich das tun!"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Oh, oups ! T'as raison, Albert. J'y penserai la prochaine fois !"
