L23_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L24_1 = "전 오래 전부터 준비해 왔던 계획을 마침내 성사시켰습니다."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "私は昔から準備していた計画を実行することができました。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "I've finally accomplished something I've been planning for a long time."
L23_1.m_Talk_ENG = L24_1
L24_1 = "我準備了很久的計畫前不久終於成功了。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ในที่สุดผมก็บรรลุสิ่งที่ผมวางแผนมานาน"
L23_1.m_Talk_THA = L24_1
L24_1 = "Cuối cùng thì tôi cũng đã hoàn thành được mục tiêu đã lên kế hoạch từ lâu."
L23_1.m_Talk_VTN = L24_1
L24_1 = "我准备了好久的计划前不久终于成功了。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Ich habe endlich etwas erreicht, das ich schon lange geplant hatte."
L23_1.m_Talk_DEU = L24_1
L24_1 = "J'ai finalisé un hack sur lequel que je travaillais depuis un moment."
L23_1.m_Talk_FRA = L24_1
