L25_1 = "바로 스위스 은행의 전산망을 뚫는 것 말이죠."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "スイス銀行のコンピューターネットワークをハッキングする計画です。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "I finally got through to the Swiss banks' network."
L24_1.m_Talk_ENG = L25_1
L25_1 = "那就是突破瑞士銀行的電腦網路。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ในที่สุดผมก็เจาะเข้าเครือข่ายธนาคารสวิสได้"
L24_1.m_Talk_THA = L25_1
L25_1 = "Tôi đã thâm nhập được vào mạng lưới các ngân hàng Thụy Sĩ."
L24_1.m_Talk_VTN = L25_1
L25_1 = "那就是突破瑞士银行的防火墙。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Ich habe das Netz der Schweizer Banken infiltriert."
L24_1.m_Talk_DEU = L25_1
L25_1 = "J'ai enfin infiltré le réseau des banques suisses."
L24_1.m_Talk_FRA = L25_1
