L26_1 = "뭐야? 정말 해낸 거야?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "えっ？　できたの？"
L25_1.m_Talk_JPN = L26_1
L26_1 = "What? You really pulled that off?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "什麼？真的嗎？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ว่าไงนะ? ทำได้จริงๆ เหรอ?"
L25_1.m_Talk_THA = L26_1
L26_1 = "Gì cơ? Cậu thực sự làm được điều đó á?"
