L26_1.m_Face = L27_1
L26_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L26_1.m_Pos = "C"
L27_1 = "꽤 하네? 보안으로 따지면 관리국이랑도 맞먹을 만한 곳이잖아?"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "やるわね？　セキュリティで言えば、管理局と張り合うくらいの場所じゃない。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "That's pretty impressive. The security for those banks are almost as robust as the Administration itself."
L26_1.m_Talk_ENG = L27_1
L27_1 = "挺厲害的啊？那邊的資安水準不是可以和管理局匹敵嗎？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "น่าประทับใจมาก การรักษาความปลอดภัยของธนาคารพวกนั้นเกือบจะแน่นหนาพอๆ กับขององค์การบริหารโลกเลยนะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Ấn tượng đấy. Quy trình bảo mật trong các ngân hàng đó mạnh ngang ngửa với Cục Quản Lý luôn rồi."
L26_1.m_Talk_VTN = L27_1
L27_1 = "挺厉害的啊？那边的安保水平不是可以和管理局媲美吗？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Die Sicherheitsvorkehrungen dieser Banken sind fast so solide wie die der Administration."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Très impressionnant. Ces banques sont presque aussi sécurisées que l'Administration elle-même."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
