L27_1.m_Pos = "C"
L28_1 = "그래서 어떻게 했는데? 비밀 거래 리스트라도 손에 넣었어?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "それで、どうなったの？　秘密取引リストでも手に入った？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "So what did you do with that? Did you find a secret roster of account holders with dirty money?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "所以你做了什麼？有拿到什麼秘密交易清單嗎？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "แล้วนายทำไงต่อ? เจอกลุ่มเจ้าของบัญชีลับที่มีเงินสกปรกรึเปล่า?"
L27_1.m_Talk_THA = L28_1
L28_1 = "Vậy bạn đã làm gì? Bạn có tìm thấy danh sách bí mật chứa tên các chủ tài khoản gửi tiền bẩn không?"
L27_1.m_Talk_VTN = L28_1
L28_1 = "所以你做了什么？是拿到什么秘密交易清单了吗？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Was hast du dort angefangen? Hast du eine geheime Liste von Kontoinhabern mit Schwarzgeld gefunden oder so?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Et alors t'as fait quoi ? T'as mis la main sur une liste secrète de comptes servant à blanchir de l'argent ?"
L27_1.m_Talk_FRA = L28_1
