L33_1 = "크으! 너처럼 제대로 된 소득도 없는 녀석에게 계좌를 만들어 주다니!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "くぅ～！　ちゃんとした所得もないやつの口座を作ったとは！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Ah! They had to make you an account when you hardly have any income!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "哇啊！他們居然會給你這種沒有收入的傢伙開戶！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "โห! พวกเขาต้องเปิดบัญชีให้นาย ทั้งที่นายแทบไม่มีรายได้เนี่ยนะ!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Ah! Họ phải tạo cho cậu một tài khoản trong khi cậu gần như chẳng có xu nào!"
L32_1.m_Talk_VTN = L33_1
