L34_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L35_1 = "스위스 은행에 굴욕을 선사했군!"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "スイス銀行に屈辱を与えたな！"
L34_1.m_Talk_JPN = L35_1
L35_1 = "You've put the Swiss banks to shame!"
L34_1.m_Talk_ENG = L35_1
L35_1 = "瑞士銀行前所未有的屈辱！"
L34_1.m_Talk_TWN = L35_1
L35_1 = "นายทำให้ธนาคารสวิสต้องอับอาย!"
L34_1.m_Talk_THA = L35_1
L35_1 = "Cậu đã khiến các ngân hàng Thụy Sĩ phải xấu hổ!"
L34_1.m_Talk_VTN = L35_1
