L36_1 = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 31225
L35_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L36_1 = "그 말대로야. 돈이 넘쳐나는 부자들만 손님으로 받던 은행이 나같이 직장도 없는 청년 백수를 고객 명단에 올리다니......"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "山ほどの大金を手にする大富豪を相手にしてる銀行が、私みたいな職場もない若者フリーターを顧客リストに加えるとは……"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Exactly. The bank that had no one but rich people as its customers ended up including a bum like me on their roster of clients..."
L35_1.m_Talk_ENG = L36_1
L36_1 = "說的沒錯。一家只接受富人的銀行竟然會把我這種沒有工作的青年列入顧客名單……"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ถูกต้อง ธนาคารที่มีแต่ลูกค้ารวยๆ ต้องมามีคนถังแตกอย่างฉันอยู่ในรายชื่อลูกค้า..."
L35_1.m_Talk_THA = L36_1
L36_1 = "Chính xác. Ngân hàng chỉ toàn những khách hàng giàu có cuối cùng lại xuất hiện một kẻ ăn bám như tôi trong danh sách khách hàng..."
L35_1.m_Talk_VTN = L36_1
L36_1 = "说的没错。一家只接受富人的银行竟然会把我这种没有工作的青年列入顾客名单……"
L35_1.m_Talk_SCN = L36_1
L36_1 = "So ist es. Eine Bank, die bislang nur reiche Kunden hatte, hat nun einen armen Typen wie mich auf der Kundenliste."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Exactement. La banque des ultra-riches compte désormais un pauvre parmi ses clients : moi."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
