L37_1 = "後々気付いた時に、どれほどの敗北感を覚えるか……想像しただけでもすごい達成感！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "By the time they realize what happened, they'll feel such a great sense of shame! Scary stuff!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "他們事後注意到時會有多大的挫敗感，想想都覺得可怕！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "กว่าพวกเขาจะรู้ว่าเกิดอะไรขึ้น พวกเขาคงละอายใจแย่! น่ากลัวชะมัด!"
L36_1.m_Talk_THA = L37_1
