L36_1.m_Talk_VTN = L37_1
L37_1 = "他们事后注意到时会有多大的挫败感，想想都觉得可怕！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Wenn sie merken, was passiert ist, werden sie vor Scham im Boden versinken!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Quand ils se rendront compte de ce que t'as fait, ils seront morts de honte ! Bien joué !"
L36_1.m_Talk_FRA = L37_1
