L41_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L42_1 = "괜찮습니다. 저도 이번만큼은 선을 넘은 게 아닌가 싶은 생각을 했으니까요."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "大丈夫です。私も今回の件は少しやり過ぎた感があったので。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "It's okay. I've been wondering if I've crossed the line this time as well."
L41_1.m_Talk_ENG = L42_1
L42_1 = "沒關係，我也覺得這次有點太超過了。"
L41_1.m_Talk_TWN = L42_1
