L41_1.m_Talk_THA = L42_1
L42_1 = "Không sao đâu. Tôi tự hỏi liệu lần này tôi có vượt qua ranh giới hay không suốt ấy mà."
L41_1.m_Talk_VTN = L42_1
L42_1 = "没关系。我也觉得这次有些越界了。"
L41_1.m_Talk_SCN = L42_1
