L50_1 = "......이해를 못하겠군요. 다섯 살 때 만든 닉네임을 왜 아직도 고집하는 겁니까?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "……理解できません。5歳の時に作ったニックネームにいまだ固執しているとは。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "I don't get it. Why do you insist on using the nickname you made up when you were five?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "……真是令人無法理解。這個暱稱是妳五歲時取的吧，妳為什麼會這麼執著？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ฉันไม่เข้าใจ ทำไมเธอถึงยืนกรานที่จะใช้ชื่อที่คิดขึ้นมาตอนห้าขวบ?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Tôi không hiểu. Tại sao cậu cứ sử dụng cái biệt hiệu được tạo ra khi cậu chỉ mới năm tuổi vậy?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "……我无法理解。这是五岁时取的吧，为什么现在还执着地用这名字啊？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Warum bestehst du darauf, einen Spitznamen zu benutzen, den du dir ausgedacht hast, als du fünf Jahre alt warst?"
