L3_1 = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@102#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 102
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 31225
L2_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L2_1.m_bWaitClick = true
