L3_1 = "UNIT_LAUGH"
L2_1.m_Face = L3_1
L3_1 = "SYLVIA_DELTA_NULL_NULL"
L2_1.m_CharStrID = L3_1
L3_1 = "L"
L2_1.m_Pos = L3_1
L3_1 = "자...... 어디 보자, 이 날을 대비해 깜짝 놀랄 사건을 준비해 뒀지. 후후훗."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "どれどれ……この日に備えてサプライズを準備しておいたのよね～ふふふっ。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Now... Let's see. I've prepared something special for this day. Heh heh heh."
L2_1.m_Talk_ENG = L3_1
L3_1 = "來……讓我看看，為了今天我可是準備了一個超級驚人的事件呢，呵呵呵。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "เอาละ... ไหนดูซิ ฉันเตรียมอะไรพิเศษๆ สำหรับวันนี้ด้วยนะ หึๆๆ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Giờ thì nhìn đi. Tôi đã chuẩn bị một thứ đặc biệt cho ngày này. He he he."
L2_1.m_Talk_VTN = L3_1
L3_1 = "来……让我看看，我可是准备了一个特别惊人的事件呢，呵呵呵。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Mal sehen … Ich habe etwas Besonderes vorbereitet. Hihihi …"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Bon... Voyons. J'ai préparé quelque chose de spécial pour aujourd'hui. Hé hé hé."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
