L4_1 = "SYLVIA_DELTA_NULL_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "L"
L3_1.m_Pos = L4_1
L4_1 = "얌전히 넘버 1 타이틀을 내놓을 준비나 하고 있으라고."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "おとなしくナンバー1の座を明け渡す準備をしてなさい。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Get ready to give up your title as number 1."
L3_1.m_Talk_ENG = L4_1
L4_1 = "你就準備乖乖讓出NO.1的頭銜吧。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เตรียมตัวเสียตำแหน่งหมายเลข 1 ได้เลย"
L3_1.m_Talk_THA = L4_1
L4_1 = "Hãy sẵn sàng từ bỏ danh hiệu số 1 của bạn đi."
L3_1.m_Talk_VTN = L4_1
L4_1 = "那家伙就乖乖准备让出1号的头衔吧！"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Mach dich bereit, deinen Rang als Nummer 1 aufzugeben."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Tu ne seras plus n°1 très longtemps."
L3_1.m_Talk_FRA = L4_1
