L5_1 = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@104#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 31225
L4_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L4_1.m_bWaitClick = true
