L5_1 = "UNIT_LAUGH"
L4_1.m_Face = L5_1
L5_1 = "KYLE_DELTA_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "R"
L4_1.m_Pos = L5_1
L5_1 = "말씀하신 거랑 다르게 죽이 잘 맞는 것 같습니다. 정신연령이 비슷해서인가요?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "言葉とは裏腹に、気が合うようですね。精神年齢が同じくらいなのでしょうか？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Despite what you've said about them, you seem to be quite compatible with the group. I guess it's because you're all just nerds after all?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "與妳說的不同，它似乎特別適合妳呢。是因為心理年齡差不多嗎？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ไม่ว่าเธอจะพูดยังไง เธอก็ดูค่อนข้างพอใจกับกลุ่มนี้นะ ฉันว่าคงเพราะทุกคนเป็นเด็กเนิร์ดกันทั้งนั้นมั้ง?"
L4_1.m_Talk_THA = L5_1
L5_1 = "Dù cậu cứ xỉa xói bọn họ, có vẻ như cậu khá hợp với cái nhóm đó đấy. Tôi đoán là vì các cậu đều là mọt sách hết đúng không?"
L4_1.m_Talk_VTN = L5_1
L5_1 = "与您所说的不同，它似乎特别适合您呢。是因为心理年龄差不多吗？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Trotz deiner Beschwerden über sie scheinst du doch ganz gut mit ihnen klarzukommen. Das liegt wohl daran, dass ihr halt alle nur Nerds seid, was?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Vous êtes beaucoup plus compatible avec ce groupe que vous ne le prétendez. Vous ressemblez beaucoup à ces nerds."
L4_1.m_Talk_FRA = L5_1
