L9_1 = "UNIT_LAUGH"
L8_1.m_Face = L9_1
L8_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L8_1.m_Pos = "C"
L8_1.m_bCharHologramEffect = true
L9_1 = "나야 일이 일이다 보니까 워낙 많긴 하지."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "アタシはこれが仕事だから、結構あるわよ。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I've done plenty, given the nature of my job."
L8_1.m_Talk_ENG = L9_1
L9_1 = "我幹的事情實在太多了。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ฉันทำอะไรเยอะเลย ด้วยลักษณะงานของฉันน่ะนะ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Tôi đã làm rất nhiều việc, với tính chất công việc của tôi."
L8_1.m_Talk_VTN = L9_1
L9_1 = "我嘛，由于工作的关系，有很多事情啊。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ich habe in meinem Job wirklich viel getan."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Malgré la nature de mon travail, je n'ai pas chômé."
L8_1.m_Talk_FRA = L9_1
