L10_1 = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@109#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 109
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 31225
L9_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L9_1.m_Pos = "C"
L10_1 = "굳이 그 중에 하나 꼽으라면...... 그로니아 반군 중 제일 세력이 큰 녀석들의 거점을 알아낸 것 정도?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "その中で一つ選ぶとしたら……グロニア反乱軍の中で最も勢力が大きいやつらの拠点を突き止めたってことかしら？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "If I had to pick one for this month... I guess it would be locating the largest insurgency faction in Gronia?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "如果非要我挑一個的話……像是找出了葛羅尼亞叛軍中最大勢力的據點之類的？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ถ้าต้องเลือกสักเรื่องสำหรับเดือนนี้... ฉันว่าคงเป็นการหาที่อยู่ของกลุ่มจลาจลที่ใหญ่ที่สุดในโกรเนียมั้ง?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Nếu phải chọn một việc trong tháng này... Tôi đoán việc đó sẽ là xác định vị trí của phe nổi dậy lớn nhất ở Gronia?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "如果非要我挑一个的话……找出了格罗尼雅叛军中最大势力的据点之类的？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Wenn ich eine Sache für diesen Monat aussuchen müsste … dann wäre es wohl, dass ich die größte aufständische Fraktion in Gronia aufgespürt habe."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Si je dois choisir une chose pour ce mois-ci... J'ai localisé la plus grosse faction insurgée de Gronia !"
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@110#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 110
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 31225
L10_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L10_1.m_Pos = "C"
L11_1 = "전략 위성만으로는 찾기 어려워서 놈들이 만들어 둔 인트라넷까지 뚫고 들어가는 수고가 있었지만, 정확하게 알아냈지."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "戦略衛星システムだけじゃ探せないから、やつらが作ったイントラネットを突破する必要があったけど、正確な場所を突き止めたわ。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "It was difficult to track them down with just the strategic satellite. So I had to penetrate their intranet as well, but I managed to pinpoint them."
L10_1.m_Talk_ENG = L11_1
L11_1 = "因為光靠戰略衛星很難找到，所以我費了很大力氣駭進他們的網路，最終準確找到了他們的位置。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "การจะตามตัวพวกนั้นโดยมีแค่ดาวเทียมยุทธวิธีมันยากนะ ฉันเลยต้องเจาะเข้าอินทราเน็ตของพวกมันด้วย แต่ก็หาตำแหน่งของพวกมันได้"
L10_1.m_Talk_THA = L11_1
L11_1 = "Rất khó để theo dõi chúng chỉ với vệ tinh chiến lược. Vì vậy, tôi cũng phải thâm nhập vào mạng nội bộ của bọn chúng, nhưng tôi đã tìm cách xác định vị trí chính xác của chúng."
L10_1.m_Talk_VTN = L11_1
L11_1 = "因为光靠战略卫星很难找到，所以我费了很大力气黑进他们的网络，最终准确找到了他们的位置。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Allein über den strategischen Satelliten gelang es nicht, also musste ich in ihr Intranet eindringen … Aber schließlich schaffte ich es, sie ausfindig zu machen."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Je n'ai pas pu les localiser avec le satellite stratégique. Alors j'ai dû aussi infiltrer leur intranet, mais j'ai réussi."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 31225
L11_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L11_1.m_Pos = "C"
L12_1 = "m_Crash"
L13_1 = 40
L11_1[L12_1] = L13_1
L12_1 = "이거 한 방이면 지긋지긋한 반군 잔당들의 뿌리를 뽑을 수 있을 거야!"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "これでしつこい反乱軍の残党の根っこを、一気に抜けるはず！"
L11_1.m_Talk_JPN = L12_1
L12_1 = "This one shot should be enough to uproot those scumbags once and for all!"
L11_1.m_Talk_ENG = L12_1
L12_1 = "現在可以將煩人的叛軍殘黨一網打盡了！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ภาพนี้ภาพเดียวก็น่าจะพอถอนรากถอนโคนคนสารเลวพวกนี้ให้สิ้นซากแล้ว!"
L11_1.m_Talk_THA = L12_1
L12_1 = "Một tấm hình này sẽ loại bỏ những tên cặn bã đó một lần và mãi mãi!"
