L16_1 = "잠깐! 왜 전부 그렇게 시큰둥한 반응들인데?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "ちょっと！　何よ、その微妙な反応は？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Hang on! What's with the lack of enthusiasm?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "等一下！為什麼你們的反應這麼冷淡？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "เดี๋ยวสิ! ทำไมดูไม่กระตือรือร้นกันเลยล่ะ?"
L15_1.m_Talk_THA = L16_1
L16_1 = "Chờ đã! Sao hờ hững quá vậy?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "等一下！为什么反应都这么冷淡？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Moment mal, warum die mangelnde Begeisterung?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Eh ben ! Cachez votre enthousiasme !"
L15_1.m_Talk_FRA = L16_1
