L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 31225
L17_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L18_1 = "하지만 전쟁은 얘기만 들어도 무서운걸요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "しかし、戦争はとても怖い。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "I'm scared of war. Even just talking about it."
L17_1.m_Talk_ENG = L18_1
L18_1 = "因為戰爭之類的，光聽就覺得很可怕啊。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ฉันกลัวสงครามน่ะ แค่พูดก็กลัวแล้ว"
L17_1.m_Talk_THA = L18_1
L18_1 = "Tôi sợ chiến tranh. Thậm chí chỉ nói về nó cũng khiến tôi sợ hãi."
L17_1.m_Talk_VTN = L18_1
L18_1 = "不过战争之类的，听听都觉得很可怕啊。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Ich habe Angst vor Krieg, selbst wenn ich nur darüber rede."
L17_1.m_Talk_DEU = L18_1
L18_1 = "J'ai peur de la guerre. Je veux même pas en parler."
L17_1.m_Talk_FRA = L18_1
