L18_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L19_1 = "맞아. 나는 피만 봐도 경기를 일으키는 사람이라고."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "そうそう。私は血を見ただけでも失神しちゃうから。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Ditto. I freak out even when I catch a glimpse of blood."
L18_1.m_Talk_ENG = L19_1
L19_1 = "就是啊，我是那種一看見血就會頭暈的人呢。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "เห็นด้วย แค่เห็นเลือดนิดหน่อยฉันก็สติแตกแล้ว"
L18_1.m_Talk_THA = L19_1
L19_1 = "Tôi cũng thế. Tôi phát hoảng ngay cả khi mới chỉ nhìn thấy máu."
L18_1.m_Talk_VTN = L19_1
L19_1 = "没错。我可是一看见血就头晕啊。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Ich auch. Ich flippe schon aus, wenn ich ein Tröpfchen Blut sehe."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Pareil. Je ne supporte pas la vue du sang."
L18_1.m_Talk_FRA = L19_1
