L24_1 = "UNIT_PRIDE"
L23_1.m_Face = L24_1
L23_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L23_1.m_Pos = "C"
L24_1 = "넘버 1이라고 자부할 정도니 분명 대단한 일을 벌였겠지?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "ナンバー1っていうくらいだから、アタシたちよりもすごいんでしょうね？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "You'd better have something really impressive since you call yourself number 1."
L23_1.m_Talk_ENG = L24_1
L24_1 = "既然敢自稱NO.1，那肯定做了什麼不得了的事情吧？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "หวังว่าจะมีอะไรที่น่าประทับใจจริงๆ นะ ในเมื่อคุณเรียกตัวเองว่าหมายเลข 1 น่ะ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Tốt nhất là bạn nên giới thiệu một thứ thực sự ấn tượng vì bạn tự gọi mình là số 1."
L23_1.m_Talk_VTN = L24_1
L24_1 = "既然敢自称1号，那肯定做了什么不得了的事情吧？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Du hast hoffentlich etwas wirklich Beeindruckendes, da du dich ja selbst Nummer 1 nennst."
L23_1.m_Talk_DEU = L24_1
L24_1 = "J'espère que tu as quelque chose de vraiment impressionnant et qui justifie que tu sois le numéro 1."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@124#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 31225
L24_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "SYLVIA_DELTA_NICK_NULL"
L24_1.m_Pos = "C"
L25_1 = "미리 말해두는데 저 녀석들처럼 시시한 일을 자랑이라고 떠벌렸다간 엉덩이를 걷어 차 줄거야."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "言っておくけど、あいつらみたいなつまんないこと話し始めたら、蹴っ飛ばすわよ。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "And let me warn you, if it's something lame like those guys, I'm going to kick your butt."
L24_1.m_Talk_ENG = L25_1
L25_1 = "先說好，如果你像那兩個傢伙一樣，把一些無聊的事情誇大其詞，信不信我會踢爛你的屁股。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "และขอเตือนไว้ก่อนนะ ถ้าเป็นอะไรเห่ยๆ แบบพวกนั้น ฉันเตะก้นคุณแน่"
L24_1.m_Talk_THA = L25_1
L25_1 = "Và cảnh báo trước nhé, nếu đó là một thứ tào lao như những người còn lại, tôi sẽ đá vào mông của bạn đấy."
L24_1.m_Talk_VTN = L25_1
L25_1 = "提前说一下，如果你像那两个家伙一样把一些无聊的事情夸大其词，信不信我一脚就把你踹翻。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Wenn es so etwas Langweiliges ist wie bei diesen Typen, kriege ich die Krise!"
L24_1.m_Talk_DEU = L25_1
L25_1 = "Et je te préviens, si c'est un truc bidon comme ces deux-là, je te botte le cul."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
