L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 31225
L26_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
