L27_1 = "그렇다면 직접 듣고 판단하는 게 좋겠군."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "そしたら、直接聞いて判断すればいい。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "You'd better hear it yourself first."
L26_1.m_Talk_ENG = L27_1
L27_1 = "那你就親自聽聽看吧。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ฟังก่อนแล้วค่อยว่ากัน"
L26_1.m_Talk_THA = L27_1
L27_1 = "Tốt hơn hết là bạn nên tự mình nghe trước đi."
L26_1.m_Talk_VTN = L27_1
L27_1 = "那你就亲自听听看吧。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Hör es dir am besten erst einmal selbst an."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Tu vas pas en revenir."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
