L30_1 = "不可能……從外部接近那裡……物理意義上行不通的吧？"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ไม่มีทาง... มันเป็นไปไม่ได้เลยที่จะเจาะเข้าไปจากภายนอก!"
