L32_1 = "맞아, 하지만 그런 불가능한 일을 가능하게 만드는 것이 진정한 해커의 실력이라고 할 수 있겠지."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "そうだ。しかし、不可能なことを可能にするのが真のハッカーの実力と言えるだろう。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Yes, but it's the hacker's job to make the impossible possible."
L31_1.m_Talk_ENG = L32_1
L32_1 = "沒錯，但是將不可能化為可能才是真正的駭客。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ใช่ แต่งานของแฮ็กเกอร์คือการทำให้สิ่งที่เป็นไปไม่ได้เป็นไปได้"
L31_1.m_Talk_THA = L32_1
L32_1 = "Đúng, nhưng nhiệm vụ của hacker là biến điều không thể thành có thể."
L31_1.m_Talk_VTN = L32_1
L32_1 = "没错，但是将不可能化为可能才是真正的黑客。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ja, aber es ist schließlich die Aufgabe eines Hackers, das Unmögliche möglich zu machen."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Oui, à l'impossible nul n'est tenu, sauf les hackeurs."
L31_1.m_Talk_FRA = L32_1
