L33_1 = "내 앞을 가로막는 수많은 보안 체계와 추적을 모두 돌파해서 마침내 내가 손에 넣은 것은......"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "行く手を阻む多くのセキュリティシステムと追跡を突破し、私が手にしたものは……"
