L32_1.m_Talk_THA = L33_1
L33_1 = "Sau khi thâm nhập qua vô số giao thức bảo mật và tường lửa, cuối cùng tôi đã lấy được..."
L32_1.m_Talk_VTN = L33_1
L33_1 = "突破了无数阻碍我前进的安全系统和追踪，我终于拿到了……"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Nachdem ich unzählige Sicherheitsprotokolle und Firewalls durchdrungen hatte, konnte ich endlich …"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Après avoir franchi un nombre incalculable de protocoles de sécurité et de pare-feu, j'ai..."
L32_1.m_Talk_FRA = L33_1
