L35_1.m_Talk_THA = L36_1
L36_1 = "Cửa hàng tiện lợi huyền thoại, Apocalypse! Tôi đã lấy được xếp hạng kinh doanh của cửa hàng tàu đô đốc ở Cục Quản Lý!"
L35_1.m_Talk_VTN = L36_1
