L35_1.m_Talk_SCN = L36_1
L36_1 = "Apocalypse, der legendäre Supermarkt! Ich habe die Umsatzzahlen des Flagship-Stores bei der Administration abgegriffen!"
L35_1.m_Talk_DEU = L36_1
