L40_1.m_fTalkTime = 0.03
L41_1 = "すごい？　売上ランキングが！？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Amazing?! What's amazing at all about that stupid stunt?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "厲害？！這種蠢事哪裡厲害了？！"
L40_1.m_Talk_TWN = L41_1
