L40_1.m_Talk_THA = L41_1
L41_1 = "Kinh ngạc?! Có gì đáng kinh ngạc về trò hề ngu ngốc đó cơ chứ?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "厉害？！这种蠢事哪里厉害了？！"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Erstaunlich? Was ist an dieser beknackten Nummer erstaunlich?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "« Extraordinaire » ?! C'est une blague ?"
L40_1.m_Talk_FRA = L41_1
