L42_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L43_1 = "우리가 엄두도 못 내는 일을 태연하게 해내셨잖아!"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "私たちができないことを、平然とやってのけたじゃないか！"
L42_1.m_Talk_JPN = L43_1
L43_1 = "The leader managed to pull off something we wouldn't dare with such finesse,"
L42_1.m_Talk_ENG = L43_1
L43_1 = "不愧是老大，輕易就做到了我們做不到的事！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "หัวหน้าดึงข้อมูลที่เราไม่กล้าดึงออกมาได้อย่างมีชั้นเชิง"
L42_1.m_Talk_THA = L43_1
L43_1 = "Lãnh đạo đã cố gắng thực hiện một chuyện mà chúng tôi không dám làm bằng một sự khéo léo,"
L42_1.m_Talk_VTN = L43_1
L43_1 = "不愧是老大，轻松做到了我们做不到的事呢！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Der Anführer hat mit viel Finesse etwas geschafft, was wir uns nie zugetraut hätten."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Notre leader a réussi avec brio une chose que nous n'aurions même pas tentée,"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 31225
L43_1.m_CutScenStrID = "COUNTERCASE_DELTASEVEN_SYLVIA_NORMAL_5"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L44_1 = "게다가 굳이 사소한 정보를 빼돌려서 자신의 대범함을 드러내시다니!"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "それに寛大さすら感じます！　数多く存在する情報からあえて取るに足らないものを選んでくるとは！"
L43_1.m_Talk_JPN = L44_1
L44_1 = "intentionally stealing the most petty data to show boldness!"
L43_1.m_Talk_ENG = L44_1
L44_1 = "而且特意去竊取這種瑣碎資訊，更彰顯了老大的度量！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ด้วยการจงใจขโมยข้อมูลที่กระจอกที่สุดเพื่อแสดงความกล้าหาญ!"
L43_1.m_Talk_THA = L44_1
L44_1 = "cố tình ăn cắp những dữ liệu vụn vặt nhất để thể hiện sự táo bạo!"
L43_1.m_Talk_VTN = L44_1
L44_1 = "而且特意去窃取些琐碎信息，更彰显了老大的王者风范！"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Er hat vorsätzlich die unbedeutendsten Daten gestohlen, um seine Kühnheit unter Beweis zu stellen!"
L43_1.m_Talk_DEU = L44_1
L44_1 = "il a volé des données sans intérêt au mépris de tous les dangers !"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
