L44_1.m_CharStrID = "ALBERT_NPC_NULL_NULL"
L45_1 = "그 점에 동경하게 되어 버려! 평생 따르겠습니다, 넘버 1!"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "憧れます！　一生ついていきます、ナンバー1！"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I can't help but admire the leader for that! I will follow you all my life, number 1!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "太讓人熱血沸騰了！我一輩子都跟隨您的，NO.1。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ฟังแล้วก็อดชื่นชมหัวหน้าไม่ได้เลย! ผมจะตามคุณไปตลอดชีวิตนะครับ หมายเลข 1"
L44_1.m_Talk_THA = L45_1
L45_1 = "Tôi không thể không ngưỡng mộ lãnh đạo vì điều đó! Tôi sẽ đi theo anh suốt cuộc đời này, số 1!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "真是让人热血沸腾，为之折服！我要一辈子跟随您，1号。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Dafür bewundere ich den Anführer aufrichtig! Ich werde dir mein ganzes Leben lang folgen, Nummer 1!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Notre leader mérite toute mon admiration pour ça ! Je suis prêt à vous confier ma vie, numéro 1 !"
L44_1.m_Talk_FRA = L45_1
