L3_1.m_CharStrID = "MACHINEGAP_COFFIN_DARK_NULL"
L4_1 = "의미 없는 항의를 하기보다 실력을 키워서 다음 기회를 노리는 것이......"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "意味のない抗議をするより、実力を鍛えて次の機会を狙う方が……"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Rather than filing an meaningless complaint, perhaps you should build your strength and try again later—"
L3_1.m_Talk_ENG = L4_1
L4_1 = "與其進行無意義的抗議，不如好好培養實力爭取下次……"
L3_1.m_Talk_TWN = L4_1
L4_1 = "แทนที่จะร้องเรียนแบบไร้ความหมาย บางทีเธอน่าจะสั่งสมความแข็งแกร่งแล้วลองใหม่อีกครั้ง..."
L3_1.m_Talk_THA = L4_1
L4_1 = "Thay vì gửi một lời phàn nàn vô dụng, có lẽ bạn nên xây dựng sức mạnh của mình và thử lại sau—"
L3_1.m_Talk_VTN = L4_1
L4_1 = "与其进行无意义的抗议，不如好好培养实力争取下次……"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Anstatt eine sinnlose Beschwerde einzureichen, solltest du lieber deine Kräfte sammeln und es erneut versuchen."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Plutôt que de remplir une réclamation inutile, vous devriez faire des progrès et retenter votre chance—"
L3_1.m_Talk_FRA = L4_1
