L18_1 = "뭐? 그러고 보니 그런 것 같기도 한데......"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "えっ？　そういえば、そんな気もしなくもないですね……"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Huh? Now that you mention it, I think I see the resemblance..."
L17_1.m_Talk_ENG = L18_1
L18_1 = "什麼？經妳這麼一說確實……"
L17_1.m_Talk_TWN = L18_1
L18_1 = "หืม? พอเธอพูดแล้วฉันว่าก็คล้ายอยู่นะ..."
L17_1.m_Talk_THA = L18_1
L18_1 = "Hử? Bạn nói tôi mới để ý đấy, giống nhau thật..."
L17_1.m_Talk_VTN = L18_1
L18_1 = "什么？你这么一说确实……"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Hm? Nun, da du es erwähnst, bemerke ich eine gewisse Ähnlichkeit …"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Hein ? Maintenant que vous le dites, c'est vrai qu'il lui ressemble..."
