L19_1 = "아, 여길 보세요. 조금 전까지 누군가와 통신을 하고 있었나 봐요."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "あっ、ここを見てください。今さっきまで誰かと通信していたようです。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Oh, and look here. Our suspect must have been communicating with someone just till now."
L18_1.m_Talk_ENG = L19_1
L19_1 = "啊，來看看這個。看來它剛才在跟誰通訊啊。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "อ๊ะ ดูนี่สิ ผู้ต้องสงสัยของเราสื่อสารกับใครสักคนอยู่ก่อนหน้านี้แน่ๆ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Ồ, và nhìn nè. Kẻ tình nghi của chúng ta vừa mới liên lạc với ai đó."
L18_1.m_Talk_VTN = L19_1
L19_1 = "来看看这个，他好像刚刚在跟某人通话。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Oh, und sieh mal hier. Unser Verdächtiger hat gerade eben noch mit jemandem kommuniziert."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Oh, et regardez ça. Notre suspect était en pleine communication avec quelqu'un."
L18_1.m_Talk_FRA = L19_1
