L25_1.m_CharStrID = "MAVERICK_NPC_NULL_NULL"
L26_1 = "학창 시절 몰래 게임하다가 엄마가 들어올 때 화면을 전환하던 실력이 여전한 걸, 앨버트!"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "学生時代、隠れてゲームしてて母親が入ってきた瞬間、画面を切り換えてた実力が今もなお健在だな、アルバート！"
L25_1.m_Talk_JPN = L26_1
L26_1 = "I guess you still got your reflexes from switching your computer screen when your mom walked in on you, Albert!"
L25_1.m_Talk_ENG = L26_1
L26_1 = "我想起學生時代偷偷玩遊戲，因為媽媽進來所以快速切換螢幕的時候了，你這手法還是一如既往啊，亞伯特！"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ดูท่านายยังมีปฏิกิริยาตอบรับดีจากการต้องคอยสลับหน้าจอคอมพิวเตอร์ เวลาที่แม่เดินเข้ามาในห้องนะ อัลเบิร์ต"
L25_1.m_Talk_THA = L26_1
L26_1 = "Tôi đoán cậu vẫn còn giữ phản xạ đổi màn hình máy tính khi mẹ cậu bước vào, Albert ha!"
L25_1.m_Talk_VTN = L26_1
L26_1 = "我想起学生时代偷偷玩游戏，妈妈进来快速切屏的时候了。你这手速不减当年啊，艾伯特！"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Ich schätze, du hast noch Übung darin, den Bildschirm zu wechseln, wenn deine Mama ins Zimmer kam, Albert!"
L25_1.m_Talk_DEU = L26_1
L26_1 = "T'as gardé quelques réflexes de l'époque où tu planquais ton écran pour pas te faire choper par ta mère, Albert !"
L25_1.m_Talk_FRA = L26_1
