L35_1 = "......그럼 넘버 1으로서 말하는데, 조직은 이 시간부로 해산이야."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "……それじゃ、ナンバー1として言うけど。組織は今をもって解散よ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Then let me say this as the new number one... I'm disbanding this group, effective immediately."
L34_1.m_Talk_ENG = L35_1
L35_1 = "……那麼我作為NO.1宣佈，這個組織從現在起正式解散。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "งั้นขอฉันพูดในฐานะหมายเลข 1 คนใหม่นะ... ฉันขอยุบกลุ่มนี้ มีผลทันที"
L34_1.m_Talk_THA = L35_1
L35_1 = "Vậy thì hãy để tôi tuyên bố điều này với tư cách là số một mới... Tôi sẽ giải tán nhóm này, có hiệu lực ngay lập tức."
L34_1.m_Talk_VTN = L35_1
L35_1 = "……那么我作为1号宣布，这个组织从现在起正式解散。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Und als erste Amtshandlung als Nummer 1 … löse ich diese Gruppe mit sofortiger Wirkung auf."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Alors laissez-moi vous dire un truc en tant que nouveau numéro 1... Je dissous ce groupe, à compter de maintenant."
L34_1.m_Talk_FRA = L35_1
